const $=s=>document.querySelector(s),cats=['Дека','Колёса','Руль','Вилка','Зажим','Грипсы','Шкурка','Рулевая'];
// All unspecified masses, prices and performance values are explicitly prototype estimates.
const data=[
[['Apex','4.5″ · 490 мм',1400,24900,114,0],['Apex','5″ · 490 мм',1380,25900,127,0],['Apex','6″ · 534 мм',1730,29900,152,0],['По референсу','Black Park · 480 × 120',1350,7900,120,1]],
[['Root Industries','Air · 110 мм / пара',440,6900,110,1],['Ethic','Incube · 110 мм / пара',460,4900,110,1],['Tech Team','Колёса · 110 мм / пара',500,2900,110,1],['По референсу','Mushroom · black / пара',460,4900,110,1],['По референсу','Neochrome · 5-spoke / пара',440,5900,110,1],['Root Industries','Honeycore · purple / пара',406,7900,110,1],['По референсу','Silver · 5-spoke / пара',460,3900,110,1]],
[['Ethic','Trianon · 620 × 560',1050,7900,620,1],['Apex','Bol Bar STD · 590 × 560',1170,12900,590,0],['Tech Team','T-bar · сталь',1250,3900,600,1],['По референсу','Black Y · 600 × 580',850,4900,600,1]],
[['Ethic','Вилка · IHC',300,5900,110,1],['Root Industries','Вилка · IHC',320,6900,110,1],['Tech Team','Вилка · IHC',380,2900,110,1],['По референсу','Black · скульптурная вилка',320,2900,110,1]],
[['Root Industries','Зажим · 2 болта',90,1900,0,1],['Ethic','Зажим · 2 болта',85,2200,0,1],['Tech Team','Зажим · 2 болта',110,900,0,1],['По референсу','Black · узкий зажим',85,900,0,1]],
[['ODI','Longneck · пара',150,1590,0,1],['Ethic','DTC · пара',140,1290,0,1],['Tech Team','Грипсы · пара',160,690,0,1],['По референсу','Black · мелкий рельеф / пара',130,690,0,1]],
[['Mob Grip','Чёрная шкурка',65,890,0,1],['Ethic','Шкурка · graphic',60,990,0,1],['Tech Team','Шкурка · classic',70,490,0,1],['По референсу','Plain Black · без рисунка',60,490,0,1]],
[['Apex','Integrated 1⅛″',75,3900,0,1],['Ethic','Integrated 1⅛″',70,2900,0,1],['Tech Team','Integrated 1⅛″',85,1490,0,1]]];
// Append variants to preserve saved garage selections.
data[5].push(['Ride Action','Storm · чёрные / пара',100,990,165,0],['Ride Action','Storm · фиолетовые / пара',100,990,165,0]);
data[6].push(...rideGriptapes.map(p=>['Ride Action',p.name+' · 620 × 170',80,800,620,0]));
let selected=[3,6,3,3,3,3,3,0],category=0,color='#bade44',auto=false,exploded=false;let garage=[];try{garage=JSON.parse(localStorage.getItem('scoot-garage')||'[]')}catch{}const money=n=>n.toLocaleString('ru-RU')+' ₽',part=i=>data[i][selected[i]];
const icons=[`<path d="M5 34L48 21l9 5-44 14z"/><path d="M47 23l-5-12 6-3 7 16"/>`,`<circle cx="30" cy="27" r="18"/><circle cx="30" cy="27" r="11" fill="none" stroke="#d5ed78" stroke-width="4"/><circle cx="30" cy="27" r="4" fill="#aaa"/>`,`<path d="M28 43V12H9V8h43v4H33v31z"/>`,`<path d="M27 7h8v22l9 13h-7L31 33l-7 9h-7l10-15z"/>`,`<rect x="20" y="10" width="24" height="31" rx="5"/><path d="M23 20h18M23 30h18" stroke="#aaa" stroke-width="3"/>`,`<rect x="5" y="20" width="50" height="12" rx="5"/><path d="M12 21v10m6-10v10m6-10v10m6-10v10m6-10v10m6-10v10m6-10v10" stroke="#aaa"/>`,`<path d="M7 32l41-17 7 11-41 17z"/><path d="M15 33l30-12" stroke="#aaa"/>`,`<ellipse cx="30" cy="20" rx="18" ry="8"/><path d="M12 20v13c0 10 36 10 36 0V20"/><ellipse cx="30" cy="20" rx="10" ry="4" fill="#ddd"/>`];
function art(i){return `<svg viewBox="0 0 60 50" fill="#40483a">${icons[i]}</svg>`}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
function render(){ $('#tabs').innerHTML=cats.map((c,i)=>`<button aria-label="${c}" title="${c}" aria-pressed="${i===category}" class="${i===category?'active':''}" data-cat="${i}">${art(i)}<span>${c}</span></button>`).join('');$('#categoryTitle').textContent=cats[category];$('.catalog-head h2').textContent=cats[category];$('#partCount').textContent=`0${category+1} / 08`;let brands=[...new Set(data[category].map(p=>p[0]))],filter=$('#brand').value;$('#brand').innerHTML='<option value="all">Все бренды</option>'+brands.map(b=>`<option>${b}</option>`).join('');$('#brand').value=brands.includes(filter)?filter:'all';$('#parts').innerHTML=data[category].map((p,i)=>[p,i]).sort((a,b)=>category===6?Number(a[1]<4)-Number(b[1]<4):0).map(([p,i])=>$('#brand').value!=='all'&&p[0]!==$('#brand').value?'':`<button class="part ${selected[category]===i?'selected':''}" data-part="${i}"><span class="part-art">${art(category)}</span><div><small>${p[0].toUpperCase()} ${p[0]==='Tech Team'?'· РФ':''}</small><h3>${p[1]}</h3><div class="variant-note">${variantNotes[category][i]}</div><p>${p[5]?'≈ ':''}${p[2]} г <span style="color:#bbb"> / </span> ≈ ${money(p[3])}</p></div><span class="tick">${selected[category]===i?'✓':'+'}</span></button>`).join('');let w=selected.reduce((a,_,i)=>a+part(i)[2],0)+70;$('#weight').innerHTML=`≈ ${(w/1000).toFixed(2).replace('.',',')} <span>кг</span>`;$('#price').textContent='≈ '+money(selected.reduce((a,_,i)=>a+part(i)[3],0));let scores=[Math.round(85-(w-3400)/70),Math.round(70+(part(0)[4]-114)/2),Math.round(85-(w-3400)/35)];$('#stats').innerHTML=['Накат','Контроль','Вращения'].map((c,i)=>`<div class="stat"><span>${c}</span><div class="bar"><i style="width:${Math.max(20,Math.min(98,scores[i]))}%"></i></div><b>${Math.max(20,Math.min(98,scores[i]))}</b></div>`).join('');$('#buildList').innerHTML=cats.map((c,i)=>`<div class="build-item"><span>${c} · ${part(i)[5]?'≈ ':''}${part(i)[2]} г</span>${part(i)[0]} ${part(i)[1]}</div>`).join('')+'<div class="build-item"><span>Крепёж и проставки</span>≈ 70 г</div>';$('#count').textContent=garage.length;$('#colors').innerHTML=['#bade44','#282d29','#a7a9b0','#a896d6','#e88955'].map(c=>`<button aria-label="Цвет ${c}" class="swatch ${c===color?'active':''}" data-color="${c}" style="background:${c}"></button>`).join('');}
$('#tabs').onclick=e=>{let b=e.target.closest('[data-cat]');if(b){category=+b.dataset.cat;$('#brand').value='all';render();studio?.setCategory(category);refreshThumbnails();if(category===6&&selected[6]<4)$('#parts').scrollTo({top:0});else centerPart()}};$('#parts').onclick=e=>{let b=e.target.closest('[data-part]');if(b){selected[category]=+b.dataset.part;render();build();centerPart()}};$('#brand').onchange=()=>{render();refreshThumbnails()};$('#colors').onclick=e=>{let b=e.target.closest('[data-color]');if(b){color=b.dataset.color;render();build();centerPart()}};
function modal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}$('.close').onclick=()=>$('#modal').close();$('#info').onclick=()=>modal(`<div class="eyebrow">О ПРОТОТИПЕ</div><h2>Реальные бренды. Игровая мастерская.</h2><p>В каталоге представлены Apex, Ethic, Root Industries, ODI, Mob Grip, российский Tech Team и Ride Action. Деки Apex и руль Bol STD реконструированы по опубликованным размерам и референсам. Остальные детали — приближённые реконструкции характерных форм брендов. Это не заводские CAD-модели; точность логотипов, цвета и мелких элементов может отличаться от оригинала.</p><p>Проверены массы дек Apex: 4.5″ × 490 мм — 1400 г, 5″ × 490 мм — 1380 г, 6″ × 534 мм — 1730 г. Масса Bol STD 590 × 560 — 1170 г по данным Apex. У шкурок Ride Action масса исходного листа — 80 г (620 × 170 мм), у грипсов Storm — 100 г за пару (165 мм). Шкурка в игре подрезается под деку; масса листа до подрезки. Остальные массы и все цены приблизительны. Крепёж учитывается отдельно.</p><p>Шкурки Ride Action используют оригинальные рисунки из каталога бренда, наложенные на 3D-деку. <a href="https://rideaction.ru/catalog/detali/gripsy/gripsy-ride-action-storm-chernye/" target="_blank" rel="noopener">Ride Action Storm</a> · <a href="https://rideaction.ru/catalog/detali/shkurki/shkurka-ride-action-ksd-banana/" target="_blank" rel="noopener">KSD Banana</a> · <a href="https://rideaction.ru/catalog/detali/shkurki/shkurka-ride-action-ksd-tie-dye/" target="_blank" rel="noopener">KSD Tie-Dye</a> · <a href="https://rideaction.ru/catalog/detali/shkurki/shkurka-ride-action-ksd-ufo/" target="_blank" rel="noopener">KSD UFO</a> · <a href="https://rideaction.ru/catalog/detali/shkurki/shkurka-ride-action-ksd-boom-krasnaya/" target="_blank" rel="noopener">KSD Boom · красная</a> · <a href="https://rideaction.ru/catalog/detali/shkurki/shkurka-ride-action-ksd-vibe-bubble-gum/" target="_blank" rel="noopener">KSD Vibe · Bubble Gum</a> · <a href="https://rideaction.ru/catalog/detali/shkurki/shkurka-ride-action-ksd-fire-v2-zelenyy/" target="_blank" rel="noopener">KSD Fire V2 · зелёная</a> · <a href="https://rideaction.ru/catalog/detali/shkurki/shkurka-ride-action-mandala-fioletovaya/" target="_blank" rel="noopener">Mandala · фиолетовая</a>.</p><p>Источники: <a href="https://apexproscooters.com/shop/4-5-deck/" target="_blank" rel="noopener">Apex 4.5″</a> · <a href="https://apexproscooters.com/shop/5-deck-blue/" target="_blank" rel="noopener">Apex 5″</a> · <a href="https://apexproscooters.com/shop/apex-6-deck/" target="_blank" rel="noopener">Apex 6″</a> · <a href="https://apexproscooters.com/shop/apex-standard-handlebars/" target="_blank" rel="noopener">Apex Bol STD</a> · <a href="https://rootindustries.com/collections" target="_blank" rel="noopener">Root Industries</a> · <a href="https://techteam.ru" target="_blank" rel="noopener">Tech Team</a></p><p>Показатели — условные баллы 0–100. Геометрия стилизована, совместимость конкретных товаров нужно проверять по диаметру руля, компрессии, осям и габаритам колёс. Это ещё не технический подборщик для покупки.</p>`);
$('#save').onclick=()=>{garage.push({name:'Кастом '+String(garage.length+1).padStart(3,'0'),selected:[...selected],color});try{localStorage.setItem('scoot-garage',JSON.stringify(garage));toast('Сборка сохранена в твоём гараже');render();refreshThumbnails()}catch{garage.pop();toast('Не удалось сохранить: память браузера недоступна')}};$('#garage').onclick=showGarage;function showGarage(){modal('<div class="eyebrow">ТВОЯ КОЛЛЕКЦИЯ</div><h2>Мой гараж</h2>'+(garage.length?garage.map((g,i)=>`<div class="saved"><b>${g.name}</b><button data-load="${i}">Открыть</button><button data-delete="${i}" aria-label="Удалить ${g.name}">✕</button></div>`).join(''):'<p>Здесь будут твои сборки. Выбери детали и нажми «Сохранить сборку».</p>'));}$('#modalContent').onclick=e=>{if(e.target.dataset.load!==undefined){let g=garage[+e.target.dataset.load];selected=[...g.selected];color=g.color;render();build();$('#modal').close()}if(e.target.dataset.delete!==undefined){garage.splice(+e.target.dataset.delete,1);try{localStorage.setItem('scoot-garage',JSON.stringify(garage))}catch{}render();showGarage()}};render();
let studio;
try{studio=startStudio($('#viewer'));studio.update(selected,color,category);$('#loading').remove();refreshThumbnails();}catch(error){$('#loading').textContent='Не удалось запустить 3D. Обнови страницу в браузере с поддержкой WebGL.';console.error(error)}
function refreshThumbnails(){if(!studio)return;document.querySelectorAll('[data-part]').forEach(b=>{let i=+b.dataset.part;b.querySelector('.part-art').innerHTML=`<img src="${studio.thumbnail(category,i)}" alt="3D ${data[category][i][0]} ${data[category][i][1]}">`})}
function build(){if(studio){studio.update(selected,color,category);refreshThumbnails()}}
$('#rotate').onclick=()=>$('#rotate').classList.toggle('on',studio?.rotate());
$('#reset').onclick=()=>{studio?.reset();$('#explode').classList.remove('on')};
$('#explode').onclick=()=>$('#explode').classList.toggle('on',studio?.explode());



document.addEventListener('scooter-thumbnails-refresh',refreshThumbnails);
const refButton=document.createElement('button');refButton.className='reference-link';refButton.textContent='Фото-референсы ↗';document.querySelector('.filter').appendChild(refButton);refButton.onclick=()=>modal(`<h2>Твои референсы</h2><p>Стартовая сборка повторяет чёрный силуэт с плавным Y-рулём. Формы восстановлены по фото; размеры и масса деталей по референсам — приблизительные.</p><div class="reference-gallery"><figure><img src="assets/default-reference.jpg" alt="Исходный самокат"><figcaption>Стартовая сборка</figcaption></figure><figure><img src="assets/mushroom-reference.jpg" alt="Колесо Mushroom"><figcaption>Mushroom · рисунок из фото</figcaption></figure><figure><img src="assets/neochrome-reference.jpg" alt="Радужное колесо"><figcaption>Neochrome · пять спиц</figcaption></figure><figure><img src="assets/honeycore-reference.jpg" alt="Root Honeycore"><figcaption>Root Honeycore · purple</figcaption></figure></div>`);

function scrollParts(direction){const row=document.querySelector('.part');document.querySelector('#parts').scrollBy({top:direction*((row?.offsetHeight||150)+12),behavior:'smooth'});}
document.querySelector('#partsUp').onclick=()=>scrollParts(-1);document.querySelector('#partsDown').onclick=()=>scrollParts(1);document.querySelector('#parts').onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();scrollParts(e.key==='ArrowDown'?1:-1)}};
document.querySelector('#zoomIn').onclick=()=>studio?.zoom(.78);document.querySelector('#zoomOut').onclick=()=>studio?.zoom(1.28);

function centerPart(){const list=document.querySelector('#parts'),card=list.querySelector('.part.selected');if(card)list.scrollTo({top:card.offsetTop-(list.clientHeight-card.clientHeight)/2,behavior:'smooth'})}

const studioActions=document.createElement('div');studioActions.className='studio-actions';
const saveAction=document.querySelector('#save');saveAction.innerHTML='✓';saveAction.title='Сохранить сборку';saveAction.setAttribute('aria-label','Сохранить сборку');
const garageAction=document.querySelector('#garage');garageAction.innerHTML=`▣ <span id="count">${garage.length}</span>`;garageAction.title='Мой гараж';garageAction.setAttribute('aria-label','Мой гараж');
const fullscreenAction=document.createElement('button');fullscreenAction.id='fullscreen';fullscreenAction.textContent='⛶';fullscreenAction.title='На весь экран';fullscreenAction.setAttribute('aria-label','На весь экран');
fullscreenAction.onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Открой игру отдельной вкладкой и поверни телефон горизонтально')}catch{toast('Полноэкранный режим недоступен в этом окне браузера')}};
studioActions.append(saveAction,garageAction,fullscreenAction);document.querySelector('.studio-top').append(studioActions);

